-- ålrium - QuizWiz: complete database schema for a NEW, empty PostgreSQL database.
-- GENERATED by scripts/build-setup-sql from db/migrations (0001 to 0004). Do not edit by hand.
--
-- Run as the role that will own the tables, connected to the new database:
--   psql "postgresql://<owner>:<password>@<host>:5432/<database>" -v ON_ERROR_STOP=1 -f db/setup.sql
--
-- Creates the tables, functions, triggers and constraints, records each migration in
-- schema_migrations (so `make migrate` later finds nothing to do), and sets the database time
-- zone to Asia/Kolkata. Inserts no questions, responses or users. Refuses to run on a database
-- that already has these tables. Requires PostgreSQL 13 or later (tested with 18).

\set ON_ERROR_STOP on
SET client_min_messages = warning;

DO $$
BEGIN
    IF to_regclass('public.questions') IS NOT NULL OR to_regclass('public.schema_migrations') IS NOT NULL THEN
        RAISE EXCEPTION 'this database already has the schema; use make migrate to upgrade it instead of db/setup.sql';
    END IF;
END $$;

-- Business dates and timestamps are Asia/Kolkata. Applies to new sessions of this database.
DO $$
BEGIN
    EXECUTE format('ALTER DATABASE %I SET timezone = %L', current_database(), 'Asia/Kolkata');
END $$;
SET timezone = 'Asia/Kolkata';

CREATE TABLE schema_migrations (
    version    text        PRIMARY KEY,
    filename   text        NOT NULL,
    checksum   text        NOT NULL,
    applied_at timestamptz NOT NULL DEFAULT now()
);

-- ============================================================================================
-- 0001_create_questions_and_responses.sql
-- ============================================================================================
BEGIN;

-- 0001: questions and responses tables, JSON validation, scoring and history rules.
-- Applied by scripts/db migrate inside a single transaction; do not add BEGIN/COMMIT.
-- Portable to PostgreSQL 13+ (gen_random_uuid() is core since 13). Confirm the
-- office server's major version before deployment.

-- ---------------------------------------------------------------------------
-- Question JSON contract
--   {"question": "<nonblank>", "options": {"A": "..","B": "..","C": "..","D": ".."}, "answer": "A".."D"}
-- Exactly these keys, string values, no extras. Always returns true/false, never NULL,
-- so malformed input cannot slip through CHECK's NULL-passes semantics.
-- ---------------------------------------------------------------------------
CREATE FUNCTION qa_is_valid_question(doc jsonb)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
PARALLEL SAFE
AS $$
DECLARE
    opt text;
BEGIN
    IF doc IS NULL OR jsonb_typeof(doc) <> 'object' THEN
        RETURN false;
    END IF;

    IF ARRAY(SELECT k FROM jsonb_object_keys(doc) AS k ORDER BY k COLLATE "C")
       IS DISTINCT FROM ARRAY['answer', 'options', 'question'] THEN
        RETURN false;
    END IF;

    IF jsonb_typeof(doc -> 'question') IS DISTINCT FROM 'string'
       OR (doc ->> 'question') ~ '^[[:space:]]*$' THEN
        RETURN false;
    END IF;

    IF jsonb_typeof(doc -> 'options') IS DISTINCT FROM 'object'
       OR ARRAY(SELECT k FROM jsonb_object_keys(doc -> 'options') AS k ORDER BY k COLLATE "C")
          IS DISTINCT FROM ARRAY['A', 'B', 'C', 'D'] THEN
        RETURN false;
    END IF;

    FOREACH opt IN ARRAY ARRAY['A', 'B', 'C', 'D'] LOOP
        IF jsonb_typeof(doc -> 'options' -> opt) IS DISTINCT FROM 'string'
           OR (doc -> 'options' ->> opt) ~ '^[[:space:]]*$' THEN
            RETURN false;
        END IF;
    END LOOP;

    IF jsonb_typeof(doc -> 'answer') IS DISTINCT FROM 'string'
       OR (doc ->> 'answer') NOT IN ('A', 'B', 'C', 'D') THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$;

COMMENT ON FUNCTION qa_is_valid_question(jsonb) IS
    'Strict validator for question JSON: exact keys question/options/answer, options exactly A-D with nonblank strings, answer in A-D. Never returns NULL.';

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------
CREATE TABLE questions (
    question_id   uuid        NOT NULL DEFAULT gen_random_uuid(),
    question_date date        NOT NULL,
    question      jsonb       NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT questions_pkey PRIMARY KEY (question_id),
    CONSTRAINT questions_question_date_key UNIQUE (question_date),
    CONSTRAINT questions_question_valid CHECK (qa_is_valid_question(question))
);

COMMENT ON TABLE questions IS 'One quiz question per calendar date (business timezone, provisionally Asia/Kolkata).';
COMMENT ON COLUMN questions.question_date IS 'Calendar date the question is scheduled for. UNIQUE: at most one per date; completeness is not enforced.';
COMMENT ON COLUMN questions.question IS 'Question JSON {question, options{A..D}, answer}. Immutable once any response exists.';

CREATE TABLE responses (
    response_id     uuid        NOT NULL DEFAULT gen_random_uuid(),
    question_id     uuid        NOT NULL,
    user_id         text        NOT NULL,
    user_name       text        NOT NULL,
    response_answer text        NOT NULL,
    is_correct      boolean     NOT NULL,
    responded_at    timestamptz NOT NULL,
    CONSTRAINT responses_pkey PRIMARY KEY (response_id),
    CONSTRAINT responses_question_id_fkey FOREIGN KEY (question_id)
        REFERENCES questions (question_id) ON DELETE RESTRICT,
    CONSTRAINT responses_question_id_user_id_key UNIQUE (question_id, user_id),
    -- The trigger normalizes; these checks also reject anything that bypasses it.
    CONSTRAINT responses_user_id_normalized CHECK (
        user_id = lower(user_id)
        AND user_id !~ '[[:space:]]'
        AND user_id ~ '^[^@]+@[^@]+$'
    ),
    CONSTRAINT responses_user_name_nonblank CHECK (
        user_name !~ '^[[:space:]]*$'
        AND user_name !~ '^[[:space:]]|[[:space:]]$'
    ),
    CONSTRAINT responses_response_answer_valid CHECK (response_answer IN ('A', 'B', 'C', 'D'))
);

COMMENT ON TABLE responses IS 'One answer per user per question. Append-only through the application path.';
COMMENT ON COLUMN responses.user_id IS 'Corporate Microsoft email, trimmed and lowercased. Stored data, not authentication.';
COMMENT ON COLUMN responses.user_name IS 'Display-name snapshot at submission time (trimmed).';
COMMENT ON COLUMN responses.is_correct IS 'Computed by trigger from questions.question->>answer; caller values ignored.';
COMMENT ON COLUMN responses.responded_at IS 'Assigned by trigger (statement_timestamp()); caller values ignored.';

-- ---------------------------------------------------------------------------
-- Locking protocol (see db/README.md):
--   * Response insert locks the parent question row FOR SHARE before scoring.
--     Concurrent submissions share the lock; an in-flight question UPDATE/DELETE
--     (which takes a row-exclusive lock) blocks it, and vice versa.
--   * Question UPDATE checks for responses in a BEFORE trigger, which runs after
--     the row lock is acquired, so the check sees any response committed by a
--     transaction it waited on (READ COMMITTED takes a fresh snapshot per statement).
--   * REPEATABLE READ edits are refused: their snapshot predates the wait.
--   The FK check alone takes FOR KEY SHARE, which does not conflict with a
--   non-key UPDATE, so the explicit FOR SHARE is required.
-- ---------------------------------------------------------------------------
CREATE FUNCTION qa_responses_before_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER  -- FOR SHARE needs UPDATE privilege; the app role should not hold it.
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    stored jsonb;
BEGIN
    NEW.user_id   := lower(regexp_replace(NEW.user_id, '^[[:space:]]+|[[:space:]]+$', '', 'g'));
    NEW.user_name := regexp_replace(NEW.user_name, '^[[:space:]]+|[[:space:]]+$', '', 'g');
    NEW.is_correct := NULL;
    NEW.responded_at := statement_timestamp();

    IF NEW.question_id IS NULL THEN
        RETURN NEW;  -- NOT NULL constraint reports it
    END IF;

    SELECT q.question INTO stored
    FROM public.questions AS q
    WHERE q.question_id = NEW.question_id
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'question % does not exist', NEW.question_id
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF NEW.response_answer IS NULL THEN
        RETURN NEW;  -- NOT NULL constraint reports it
    END IF;

    IF NEW.response_answer NOT IN ('A', 'B', 'C', 'D') THEN
        RAISE EXCEPTION 'response_answer must be one of A, B, C, D (got %)', NEW.response_answer
            USING ERRCODE = 'check_violation';
    END IF;

    NEW.is_correct := (NEW.response_answer = stored ->> 'answer');
    RETURN NEW;
END;
$$;

CREATE TRIGGER responses_before_insert
    BEFORE INSERT ON responses
    FOR EACH ROW EXECUTE FUNCTION qa_responses_before_insert();

CREATE FUNCTION qa_responses_block_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'responses are append-only: % is not allowed', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER responses_block_update_delete
    BEFORE UPDATE OR DELETE ON responses
    FOR EACH ROW EXECUTE FUNCTION qa_responses_block_mutation();

CREATE TRIGGER responses_block_truncate
    BEFORE TRUNCATE ON responses
    FOR EACH STATEMENT EXECUTE FUNCTION qa_responses_block_mutation();

CREATE FUNCTION qa_questions_before_update()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER  -- must see all responses regardless of the caller's grants
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    IF NEW.question_id IS DISTINCT FROM OLD.question_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'question_id and created_at cannot be changed'
            USING ERRCODE = 'restrict_violation';
    END IF;

    IF NEW.question IS DISTINCT FROM OLD.question
       OR NEW.question_date IS DISTINCT FROM OLD.question_date THEN
        IF current_setting('transaction_isolation') = 'repeatable read' THEN
            RAISE EXCEPTION 'question edits must run at READ COMMITTED or SERIALIZABLE isolation'
                USING ERRCODE = 'object_not_in_prerequisite_state';
        END IF;

        IF EXISTS (SELECT 1 FROM public.responses AS r WHERE r.question_id = OLD.question_id) THEN
            RAISE EXCEPTION 'question % already has responses; its date and JSON are locked', OLD.question_id
                USING ERRCODE = 'restrict_violation';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER questions_before_update
    BEFORE UPDATE ON questions
    FOR EACH ROW EXECUTE FUNCTION qa_questions_before_update();

INSERT INTO schema_migrations (version, filename, checksum) VALUES ('0001', '0001_create_questions_and_responses.sql', '3b7399e44c7995c680ad4a990752741dc2bb6dfea80129f6aaca67f7b39625dc');
COMMIT;

-- ============================================================================================
-- 0002_integer_ids_and_text_columns.sql
-- ============================================================================================
BEGIN;

-- 0002: move from UUID keys + JSONB question documents (0001) to integer identity
-- keys and separate TEXT columns. Also adds today-only submission (Asia/Kolkata).
--
-- Runs in one transaction (scripts/db migrate). Existing rows are copied, old UUIDs
-- are mapped to new integer IDs through the unique question_date, and every response
-- keeps its question, user, answer, score and timestamp. Any inconsistency raises an
-- error and the whole migration rolls back, leaving the 0001 tables untouched.
--
-- Text limits (kept in sync with the API and UI):
--   question 500, each option 200, user_id 320, user_name 200 characters.

LOCK TABLE questions, responses IN ACCESS EXCLUSIVE MODE;

-- ---------------------------------------------------------------------------
-- 1. Validate legacy data before copying.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
    bad int;
BEGIN
    SELECT count(*) INTO bad FROM questions WHERE NOT qa_is_valid_question(question);
    IF bad > 0 THEN
        RAISE EXCEPTION '0002: % legacy question(s) fail JSON validation', bad;
    END IF;

    SELECT count(*) INTO bad
    FROM questions
    WHERE char_length(question ->> 'question') > 500
       OR char_length(question -> 'options' ->> 'A') > 200
       OR char_length(question -> 'options' ->> 'B') > 200
       OR char_length(question -> 'options' ->> 'C') > 200
       OR char_length(question -> 'options' ->> 'D') > 200;
    IF bad > 0 THEN
        RAISE EXCEPTION '0002: % legacy question(s) exceed text length limits', bad;
    END IF;

    SELECT count(*) INTO bad
    FROM responses AS r
    JOIN questions AS q USING (question_id)
    WHERE r.is_correct IS DISTINCT FROM (r.response_answer = q.question ->> 'answer');
    IF bad > 0 THEN
        RAISE EXCEPTION '0002: % legacy response(s) have a score that does not match the answer key', bad;
    END IF;

    SELECT count(*) INTO bad
    FROM responses
    WHERE char_length(user_id) > 320 OR char_length(user_name) > 200;
    IF bad > 0 THEN
        RAISE EXCEPTION '0002: % legacy response(s) exceed identity length limits', bad;
    END IF;
END;
$$;

-- ---------------------------------------------------------------------------
-- 2. New tables under temporary names (index-backed constraint names must be
--    unique, so they are renamed after the old tables are dropped).
-- ---------------------------------------------------------------------------
CREATE TABLE questions_new (
    question_id    int         GENERATED ALWAYS AS IDENTITY,
    question_date  date        NOT NULL,
    question       text        NOT NULL,
    option_a       text        NOT NULL,
    option_b       text        NOT NULL,
    option_c       text        NOT NULL,
    option_d       text        NOT NULL,
    correct_answer text        NOT NULL,
    created_at     timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT questions_new_pkey PRIMARY KEY (question_id),
    CONSTRAINT questions_new_question_date_key UNIQUE (question_date),
    CONSTRAINT questions_question_text CHECK (question ~ '[^[:space:]]' AND char_length(question) <= 500),
    CONSTRAINT questions_option_a_text CHECK (option_a ~ '[^[:space:]]' AND char_length(option_a) <= 200),
    CONSTRAINT questions_option_b_text CHECK (option_b ~ '[^[:space:]]' AND char_length(option_b) <= 200),
    CONSTRAINT questions_option_c_text CHECK (option_c ~ '[^[:space:]]' AND char_length(option_c) <= 200),
    CONSTRAINT questions_option_d_text CHECK (option_d ~ '[^[:space:]]' AND char_length(option_d) <= 200),
    CONSTRAINT questions_correct_answer_check CHECK (correct_answer IN ('A', 'B', 'C', 'D'))
);

CREATE TABLE responses_new (
    response_id     int         GENERATED ALWAYS AS IDENTITY,
    question_id     int         NOT NULL,
    user_id         text        NOT NULL,
    user_name       text        NOT NULL,
    response_answer text        NOT NULL,
    is_correct      boolean     NOT NULL,
    responded_at    timestamptz NOT NULL,
    CONSTRAINT responses_new_pkey PRIMARY KEY (response_id),
    CONSTRAINT responses_new_question_id_fkey FOREIGN KEY (question_id)
        REFERENCES questions_new (question_id) ON DELETE RESTRICT,
    CONSTRAINT responses_new_question_id_user_id_key UNIQUE (question_id, user_id),
    CONSTRAINT responses_user_id_normalized CHECK (
        user_id = lower(user_id)
        AND user_id !~ '[[:space:]]'
        AND user_id ~ '^[^@]+@[^@]+$'
        AND char_length(user_id) <= 320
    ),
    CONSTRAINT responses_user_name_text CHECK (
        user_name ~ '[^[:space:]]'
        AND user_name !~ '^[[:space:]]|[[:space:]]$'
        AND char_length(user_name) <= 200
    ),
    CONSTRAINT responses_response_answer_check CHECK (response_answer IN ('A', 'B', 'C', 'D'))
);

-- ---------------------------------------------------------------------------
-- 3. Copy data. No triggers exist on the new tables yet, so legacy scores and
--    timestamps are preserved exactly.
-- ---------------------------------------------------------------------------
INSERT INTO questions_new (question_date, question, option_a, option_b, option_c, option_d, correct_answer, created_at)
SELECT question_date,
       question ->> 'question',
       question -> 'options' ->> 'A',
       question -> 'options' ->> 'B',
       question -> 'options' ->> 'C',
       question -> 'options' ->> 'D',
       question ->> 'answer',
       created_at
FROM questions
ORDER BY question_date;

CREATE TEMP TABLE qa_question_id_map ON COMMIT DROP AS
SELECT o.question_id AS old_id, n.question_id AS new_id
FROM questions AS o
JOIN questions_new AS n USING (question_date);

INSERT INTO responses_new (question_id, user_id, user_name, response_answer, is_correct, responded_at)
SELECT m.new_id, r.user_id, r.user_name, r.response_answer, r.is_correct, r.responded_at
FROM responses AS r
JOIN qa_question_id_map AS m ON m.old_id = r.question_id
ORDER BY r.responded_at, r.response_id;

-- ---------------------------------------------------------------------------
-- 4. Verify the copy: counts, mapping and every response field.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
    diff int;
BEGIN
    IF (SELECT count(*) FROM questions) <> (SELECT count(*) FROM questions_new)
       OR (SELECT count(*) FROM questions) <> (SELECT count(*) FROM qa_question_id_map) THEN
        RAISE EXCEPTION '0002: question count or ID mapping mismatch';
    END IF;

    IF (SELECT count(*) FROM responses) <> (SELECT count(*) FROM responses_new) THEN
        RAISE EXCEPTION '0002: response count mismatch';
    END IF;

    SELECT count(*) INTO diff FROM (
        (SELECT q.question_date, r.user_id, r.user_name, r.response_answer, r.is_correct, r.responded_at
         FROM responses r JOIN questions q USING (question_id)
         EXCEPT
         SELECT q.question_date, r.user_id, r.user_name, r.response_answer, r.is_correct, r.responded_at
         FROM responses_new r JOIN questions_new q USING (question_id))
        UNION ALL
        (SELECT q.question_date, r.user_id, r.user_name, r.response_answer, r.is_correct, r.responded_at
         FROM responses_new r JOIN questions_new q USING (question_id)
         EXCEPT
         SELECT q.question_date, r.user_id, r.user_name, r.response_answer, r.is_correct, r.responded_at
         FROM responses r JOIN questions q USING (question_id))
    ) AS d;
    IF diff > 0 THEN
        RAISE EXCEPTION '0002: % response row(s) differ after copy', diff;
    END IF;

    SELECT count(*) INTO diff
    FROM responses_new r JOIN questions_new q USING (question_id)
    WHERE r.is_correct IS DISTINCT FROM (r.response_answer = q.correct_answer);
    IF diff > 0 THEN
        RAISE EXCEPTION '0002: % copied score(s) disagree with correct_answer', diff;
    END IF;

    SELECT count(*) INTO diff
    FROM questions o JOIN questions_new n USING (question_date)
    WHERE o.created_at IS DISTINCT FROM n.created_at;
    IF diff > 0 THEN
        RAISE EXCEPTION '0002: % question created_at value(s) changed', diff;
    END IF;
END;
$$;

-- ---------------------------------------------------------------------------
-- 5. Replace the old tables. Dropping them also drops their 0001 triggers; the
--    protections are recreated below for the new columns.
-- ---------------------------------------------------------------------------
DROP TABLE responses;
DROP TABLE questions;
DROP FUNCTION qa_responses_before_insert();
DROP FUNCTION qa_questions_before_update();
DROP FUNCTION qa_responses_block_mutation();
DROP FUNCTION qa_is_valid_question(jsonb);

ALTER TABLE questions_new RENAME TO questions;
ALTER TABLE questions RENAME CONSTRAINT questions_new_pkey TO questions_pkey;
ALTER TABLE questions RENAME CONSTRAINT questions_new_question_date_key TO questions_question_date_key;
ALTER SEQUENCE questions_new_question_id_seq RENAME TO questions_question_id_seq;

ALTER TABLE responses_new RENAME TO responses;
ALTER TABLE responses RENAME CONSTRAINT responses_new_pkey TO responses_pkey;
ALTER TABLE responses RENAME CONSTRAINT responses_new_question_id_fkey TO responses_question_id_fkey;
ALTER TABLE responses RENAME CONSTRAINT responses_new_question_id_user_id_key TO responses_question_id_user_id_key;
ALTER SEQUENCE responses_new_response_id_seq RENAME TO responses_response_id_seq;

COMMENT ON TABLE questions IS 'One quiz question per calendar date in Asia/Kolkata.';
COMMENT ON COLUMN questions.question_date IS 'Business date (Asia/Kolkata). UNIQUE: at most one question per date; completeness is not enforced.';
COMMENT ON COLUMN questions.correct_answer IS 'A, B, C or D. Never returned to a participant before they answer.';
COMMENT ON TABLE responses IS 'One answer per user per question. Append-only through the application path.';
COMMENT ON COLUMN responses.user_id IS 'Verified corporate email, trimmed and lowercased. Stored data, not authentication.';
COMMENT ON COLUMN responses.user_name IS 'Verified display-name snapshot at submission time (trimmed).';
COMMENT ON COLUMN responses.is_correct IS 'Computed by trigger from questions.correct_answer; caller values ignored.';
COMMENT ON COLUMN responses.responded_at IS 'Assigned by trigger from clock_timestamp() after the question lock; caller values ignored.';

-- ---------------------------------------------------------------------------
-- 6. Business date, scoring and history rules.
-- ---------------------------------------------------------------------------
CREATE FUNCTION qa_business_date(ts timestamptz)
RETURNS date
LANGUAGE sql
STABLE
PARALLEL SAFE
AS $$ SELECT (ts AT TIME ZONE 'Asia/Kolkata')::date $$;

COMMENT ON FUNCTION qa_business_date(timestamptz) IS 'Calendar date of an instant in the business timezone (Asia/Kolkata).';

-- Locking protocol: a submission locks the parent question FOR SHARE; question
-- UPDATE/DELETE take a conflicting row lock. After the lock is held, a single
-- clock_timestamp() reading is both the eligibility instant (is it today in
-- Asia/Kolkata?) and the stored responded_at, so a request that waited across
-- midnight is judged by the time it actually proceeds, not its transaction start.
CREATE FUNCTION qa_responses_before_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER  -- FOR SHARE needs UPDATE privilege; the app role should not hold it.
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    q_date   date;
    q_answer text;
    instant  timestamptz;
BEGIN
    NEW.user_id   := lower(regexp_replace(NEW.user_id, '^[[:space:]]+|[[:space:]]+$', '', 'g'));
    NEW.user_name := regexp_replace(NEW.user_name, '^[[:space:]]+|[[:space:]]+$', '', 'g');
    NEW.is_correct := NULL;
    NEW.responded_at := NULL;

    IF NEW.question_id IS NULL THEN
        RETURN NEW;  -- NOT NULL constraint reports it
    END IF;

    SELECT q.question_date, q.correct_answer INTO q_date, q_answer
    FROM public.questions AS q
    WHERE q.question_id = NEW.question_id
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'question % does not exist', NEW.question_id
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF NEW.response_answer IS NULL THEN
        RETURN NEW;  -- NOT NULL constraint reports it
    END IF;

    IF NEW.response_answer NOT IN ('A', 'B', 'C', 'D') THEN
        RAISE EXCEPTION 'response_answer must be one of A, B, C, D'
            USING ERRCODE = 'check_violation';
    END IF;

    instant := clock_timestamp();
    IF q_date <> public.qa_business_date(instant) THEN
        RAISE EXCEPTION 'question % is for %, not today (%) in Asia/Kolkata',
                        NEW.question_id, q_date, public.qa_business_date(instant)
            USING ERRCODE = 'QA001';
    END IF;

    NEW.responded_at := instant;
    NEW.is_correct := (NEW.response_answer = q_answer);
    RETURN NEW;
END;
$$;

CREATE TRIGGER responses_before_insert
    BEFORE INSERT ON responses
    FOR EACH ROW EXECUTE FUNCTION qa_responses_before_insert();

CREATE FUNCTION qa_responses_block_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'responses are append-only: % is not allowed', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER responses_block_update_delete
    BEFORE UPDATE OR DELETE ON responses
    FOR EACH ROW EXECUTE FUNCTION qa_responses_block_mutation();

CREATE TRIGGER responses_block_truncate
    BEFORE TRUNCATE ON responses
    FOR EACH STATEMENT EXECUTE FUNCTION qa_responses_block_mutation();

CREATE FUNCTION qa_questions_before_update()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER  -- must see all responses regardless of the caller's grants
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    IF NEW.question_id IS DISTINCT FROM OLD.question_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'question_id and created_at cannot be changed'
            USING ERRCODE = 'restrict_violation';
    END IF;

    IF (NEW.question_date, NEW.question, NEW.option_a, NEW.option_b, NEW.option_c, NEW.option_d, NEW.correct_answer)
       IS DISTINCT FROM
       (OLD.question_date, OLD.question, OLD.option_a, OLD.option_b, OLD.option_c, OLD.option_d, OLD.correct_answer) THEN
        IF current_setting('transaction_isolation') = 'repeatable read' THEN
            RAISE EXCEPTION 'question edits must run at READ COMMITTED or SERIALIZABLE isolation'
                USING ERRCODE = 'object_not_in_prerequisite_state';
        END IF;

        -- Runs after this UPDATE holds the row lock, with a fresh snapshot.
        IF EXISTS (SELECT 1 FROM public.responses AS r WHERE r.question_id = OLD.question_id) THEN
            RAISE EXCEPTION 'question % already has responses and can no longer be changed', OLD.question_id
                USING ERRCODE = 'restrict_violation';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER questions_before_update
    BEFORE UPDATE ON questions
    FOR EACH ROW EXECUTE FUNCTION qa_questions_before_update();

INSERT INTO schema_migrations (version, filename, checksum) VALUES ('0002', '0002_integer_ids_and_text_columns.sql', '4183a4dcd99627119adc06b4e358054e4522165cd39b322954a4b0b647b9d237');
COMMIT;

-- ============================================================================================
-- 0003_jsonb_questions_text_responses.sql
-- ============================================================================================
BEGIN;

-- 0003: latest meeting decisions (2026-10-23).
--   * questions.question becomes one JSONB payload {"question","options":{"A".."D"},"answer"}
--     replacing the separate TEXT option and correct_answer columns. "answer" holds the
--     actual text of the correct option (e.g. "New Delhi"), never an option key.
--   * Several questions may share a date (no UNIQUE). The newest row for today is served.
--   * Questions are insert-only: UPDATE, DELETE and TRUNCATE are always refused.
--   * responses store actual text: question, correct_answer and response_answer
--     (the selected option's value, not its letter).
--
-- Runs in one transaction (scripts/db migrate). Tables are rebuilt so the column order
-- matches docs/latest-meeting-erd.mmd. Every question_id and response_id is preserved
-- with OVERRIDING SYSTEM VALUE, and identity sequences continue from their old position.
-- The 0002 correct_answer column is constrained to A/B/C/D, so it is unambiguously an
-- option key; it is translated to that option's text through the same row's columns.
-- Legacy rows are validated first; any inconsistency raises an error and the whole
-- migration rolls back, leaving the 0002 tables untouched.
--
-- Payload validation moved to the API (the meeting removed the database CHECK). The
-- response trigger still reads the payload defensively and refuses to score a malformed one.

LOCK TABLE questions, responses IN ACCESS EXCLUSIVE MODE;

-- ---------------------------------------------------------------------------
-- 1. Validate legacy data before transforming it.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
    bad int;
BEGIN
    SELECT count(*) INTO bad FROM questions
    WHERE correct_answer IS NULL OR correct_answer NOT IN ('A', 'B', 'C', 'D')
       OR question !~ '[^[:space:]]' OR option_a !~ '[^[:space:]]' OR option_b !~ '[^[:space:]]'
       OR option_c !~ '[^[:space:]]' OR option_d !~ '[^[:space:]]';
    IF bad > 0 THEN
        RAISE EXCEPTION '0003: % legacy question(s) have blank text or an invalid answer key', bad;
    END IF;

    -- Responses will store option text, so options must be distinguishable.
    SELECT count(*) INTO bad FROM questions
    WHERE (SELECT count(DISTINCT btrim(v)) FROM unnest(ARRAY[option_a, option_b, option_c, option_d]) AS v) <> 4;
    IF bad > 0 THEN
        RAISE EXCEPTION '0003: % legacy question(s) have duplicate option text; letters cannot be translated unambiguously', bad;
    END IF;

    SELECT count(*) INTO bad FROM responses
    WHERE response_answer IS NULL OR response_answer NOT IN ('A', 'B', 'C', 'D');
    IF bad > 0 THEN
        RAISE EXCEPTION '0003: % legacy response(s) have an answer that is not A, B, C or D', bad;
    END IF;

    SELECT count(*) INTO bad FROM responses AS r
    WHERE NOT EXISTS (SELECT 1 FROM questions AS q WHERE q.question_id = r.question_id);
    IF bad > 0 THEN
        RAISE EXCEPTION '0003: % orphaned response(s) reference a missing question', bad;
    END IF;

    SELECT count(*) INTO bad
    FROM responses AS r JOIN questions AS q USING (question_id)
    WHERE r.is_correct IS DISTINCT FROM (r.response_answer = q.correct_answer);
    IF bad > 0 THEN
        RAISE EXCEPTION '0003: % legacy response(s) have a score that does not match the answer key', bad;
    END IF;
END;
$$;

-- Old sequence positions, so the next generated IDs are unchanged by the rebuild.
CREATE TEMP TABLE qa_0003_seq ON COMMIT DROP AS
SELECT 'questions' AS t, last_value, is_called FROM questions_question_id_seq
UNION ALL
SELECT 'responses', last_value, is_called FROM responses_response_id_seq;

-- Expected response rows after translation, built from the exact question_id.
CREATE TEMP TABLE qa_0003_expected ON COMMIT DROP AS
SELECT r.response_id, r.question_id, r.user_id, r.user_name,
       q.question AS question_text,
       CASE q.correct_answer WHEN 'A' THEN q.option_a WHEN 'B' THEN q.option_b
                             WHEN 'C' THEN q.option_c WHEN 'D' THEN q.option_d END AS correct_text,
       CASE r.response_answer WHEN 'A' THEN q.option_a WHEN 'B' THEN q.option_b
                              WHEN 'C' THEN q.option_c WHEN 'D' THEN q.option_d END AS answer_text,
       r.is_correct, r.responded_at
FROM responses AS r JOIN questions AS q USING (question_id);

-- ---------------------------------------------------------------------------
-- 2. New tables under temporary names.
-- ---------------------------------------------------------------------------
CREATE TABLE questions_new (
    question_id   int         GENERATED ALWAYS AS IDENTITY,
    question_date date        NOT NULL,
    question      jsonb       NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT questions_new_pkey PRIMARY KEY (question_id)
);

CREATE TABLE responses_new (
    response_id     int         GENERATED ALWAYS AS IDENTITY,
    question_id     int         NOT NULL,
    user_id         text        NOT NULL,
    user_name       text        NOT NULL,
    question        text        NOT NULL,
    correct_answer  text        NOT NULL,
    response_answer text        NOT NULL,
    is_correct      boolean     NOT NULL,
    responded_at    timestamptz NOT NULL,
    CONSTRAINT responses_new_pkey PRIMARY KEY (response_id),
    CONSTRAINT responses_new_question_id_fkey FOREIGN KEY (question_id)
        REFERENCES questions_new (question_id) ON DELETE RESTRICT,
    CONSTRAINT responses_new_question_id_user_id_key UNIQUE (question_id, user_id),
    CONSTRAINT responses_user_id_normalized CHECK (
        user_id = lower(user_id)
        AND user_id !~ '[[:space:]]'
        AND user_id ~ '^[^@]+@[^@]+$'
        AND char_length(user_id) <= 320
    ),
    CONSTRAINT responses_user_name_text CHECK (
        user_name ~ '[^[:space:]]'
        AND user_name !~ '^[[:space:]]|[[:space:]]$'
        AND char_length(user_name) <= 200
    )
);

-- ---------------------------------------------------------------------------
-- 3. Copy. No triggers exist on the new tables yet, so legacy scores and
--    timestamps are preserved exactly.
-- ---------------------------------------------------------------------------
INSERT INTO questions_new (question_id, question_date, question, created_at)
OVERRIDING SYSTEM VALUE
SELECT question_id,
       question_date,
       jsonb_build_object(
           'question', question,
           'options', jsonb_build_object('A', option_a, 'B', option_b, 'C', option_c, 'D', option_d),
           'answer', CASE correct_answer WHEN 'A' THEN option_a WHEN 'B' THEN option_b
                                         WHEN 'C' THEN option_c WHEN 'D' THEN option_d END),
       created_at
FROM questions
ORDER BY question_id;

INSERT INTO responses_new (response_id, question_id, user_id, user_name, question, correct_answer,
                           response_answer, is_correct, responded_at)
OVERRIDING SYSTEM VALUE
SELECT response_id, question_id, user_id, user_name, question_text, correct_text,
       answer_text, is_correct, responded_at
FROM qa_0003_expected
ORDER BY response_id;

-- ---------------------------------------------------------------------------
-- 4. Verify the copy field by field.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
    diff int;
BEGIN
    IF (SELECT count(*) FROM questions) <> (SELECT count(*) FROM questions_new)
       OR (SELECT count(*) FROM responses) <> (SELECT count(*) FROM responses_new) THEN
        RAISE EXCEPTION '0003: row count mismatch after copy';
    END IF;

    SELECT count(*) INTO diff
    FROM questions AS o FULL JOIN questions_new AS n USING (question_id)
    WHERE o.question_id IS NULL OR n.question_id IS NULL
       OR o.question_date IS DISTINCT FROM n.question_date
       OR o.created_at IS DISTINCT FROM n.created_at
       OR o.question IS DISTINCT FROM n.question ->> 'question'
       OR o.option_a IS DISTINCT FROM n.question -> 'options' ->> 'A'
       OR o.option_b IS DISTINCT FROM n.question -> 'options' ->> 'B'
       OR o.option_c IS DISTINCT FROM n.question -> 'options' ->> 'C'
       OR o.option_d IS DISTINCT FROM n.question -> 'options' ->> 'D'
       OR (CASE o.correct_answer WHEN 'A' THEN o.option_a WHEN 'B' THEN o.option_b
                                 WHEN 'C' THEN o.option_c WHEN 'D' THEN o.option_d END) IS DISTINCT FROM n.question ->> 'answer';
    IF diff > 0 THEN
        RAISE EXCEPTION '0003: % question(s) differ after conversion to JSONB', diff;
    END IF;

    SELECT count(*) INTO diff
    FROM responses AS o
    JOIN questions AS q USING (question_id)
    FULL JOIN responses_new AS n USING (response_id)
    WHERE o.response_id IS NULL OR n.response_id IS NULL
       OR o.question_id IS DISTINCT FROM n.question_id
       OR o.user_id IS DISTINCT FROM n.user_id
       OR o.user_name IS DISTINCT FROM n.user_name
       OR o.is_correct IS DISTINCT FROM n.is_correct
       OR o.responded_at IS DISTINCT FROM n.responded_at
       OR n.question IS DISTINCT FROM q.question
       OR n.response_answer IS DISTINCT FROM CASE o.response_answer WHEN 'A' THEN q.option_a WHEN 'B' THEN q.option_b
                                                                    WHEN 'C' THEN q.option_c WHEN 'D' THEN q.option_d END
       OR n.correct_answer IS DISTINCT FROM CASE q.correct_answer WHEN 'A' THEN q.option_a WHEN 'B' THEN q.option_b
                                                                  WHEN 'C' THEN q.option_c WHEN 'D' THEN q.option_d END;
    IF diff > 0 THEN
        RAISE EXCEPTION '0003: % response(s) differ after translation to text', diff;
    END IF;

    SELECT count(*) INTO diff FROM responses_new
    WHERE is_correct IS DISTINCT FROM (response_answer = correct_answer);
    IF diff > 0 THEN
        RAISE EXCEPTION '0003: % translated score(s) disagree with the text values', diff;
    END IF;
END;
$$;

-- ---------------------------------------------------------------------------
-- 5. Replace the old tables. Dropping them also drops their 0002 triggers; the
--    protections are recreated below, inside this same transaction.
-- ---------------------------------------------------------------------------
DROP TABLE responses;
DROP TABLE questions;
DROP FUNCTION qa_responses_before_insert();
DROP FUNCTION qa_questions_before_update();
DROP FUNCTION qa_responses_block_mutation();

ALTER TABLE questions_new RENAME TO questions;
ALTER TABLE questions RENAME CONSTRAINT questions_new_pkey TO questions_pkey;
ALTER SEQUENCE questions_new_question_id_seq RENAME TO questions_question_id_seq;

ALTER TABLE responses_new RENAME TO responses;
ALTER TABLE responses RENAME CONSTRAINT responses_new_pkey TO responses_pkey;
ALTER TABLE responses RENAME CONSTRAINT responses_new_question_id_fkey TO responses_question_id_fkey;
ALTER TABLE responses RENAME CONSTRAINT responses_new_question_id_user_id_key TO responses_question_id_user_id_key;
ALTER SEQUENCE responses_new_response_id_seq RENAME TO responses_response_id_seq;

DO $$
BEGIN
    PERFORM setval('questions_question_id_seq', last_value, is_called) FROM qa_0003_seq WHERE t = 'questions';
    PERFORM setval('responses_response_id_seq', last_value, is_called) FROM qa_0003_seq WHERE t = 'responses';
END;
$$;

-- Latest question for a date: WHERE question_date = $1 ORDER BY created_at DESC, question_id DESC LIMIT 1.
CREATE INDEX questions_date_latest_idx ON questions (question_date, created_at DESC, question_id DESC);

COMMENT ON TABLE questions IS 'Quiz questions. Insert-only: several rows may share a date; the newest row for today is served.';
COMMENT ON COLUMN questions.question_date IS 'Business date (Asia/Kolkata). Not unique: a correction is a new row for the same date.';
COMMENT ON COLUMN questions.question IS 'JSONB {"question": text, "options": {"A".."D": text}, "answer": actual correct option text}. Validated by the API; "answer" is never returned to a participant before they respond.';
COMMENT ON TABLE responses IS 'One answer per user per question. Append-only through the application path.';
COMMENT ON COLUMN responses.user_id IS 'Verified corporate email, trimmed and lowercased. Stored data, not authentication.';
COMMENT ON COLUMN responses.user_name IS 'Verified display name at submission time, trimmed.';
COMMENT ON COLUMN responses.question IS 'Question text copied by the trigger from the referenced question payload.';
COMMENT ON COLUMN responses.correct_answer IS 'Actual correct answer text, copied by the trigger from question ->> ''answer'' of the referenced question.';
COMMENT ON COLUMN responses.response_answer IS 'Actual selected answer text (not an option label). Must equal one of the referenced question''s option values.';
COMMENT ON COLUMN responses.is_correct IS 'Computed by trigger; caller values ignored.';
COMMENT ON COLUMN responses.responded_at IS 'Assigned by trigger from clock_timestamp() after the question lock; caller values ignored.';

-- ---------------------------------------------------------------------------
-- 6. Scoring and history rules.
-- ---------------------------------------------------------------------------
-- Locks the exact referenced question FOR SHARE, then reads clock_timestamp() once:
-- that instant is both the eligibility check (is the question dated today in
-- Asia/Kolkata?) and the stored responded_at. The submitted text is matched against
-- the stored option values (trimmed, case-sensitive); the stored option text is saved.
-- The correct answer is read directly from question ->> 'answer' (actual text).
-- SQLSTATEs: QA001 not today, QA002 stored payload unusable, QA003 not an option.
CREATE FUNCTION qa_responses_before_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER  -- FOR SHARE needs UPDATE privilege; the app role should not hold it.
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    q_date   date;
    payload  jsonb;
    opts     jsonb;
    chosen   text;
    correct  text;
    instant  timestamptz;
BEGIN
    NEW.user_id   := lower(regexp_replace(NEW.user_id, '^[[:space:]]+|[[:space:]]+$', '', 'g'));
    NEW.user_name := regexp_replace(NEW.user_name, '^[[:space:]]+|[[:space:]]+$', '', 'g');
    NEW.question       := NULL;
    NEW.correct_answer := NULL;
    NEW.is_correct     := NULL;
    NEW.responded_at   := NULL;

    IF NEW.question_id IS NULL THEN
        RETURN NEW;  -- NOT NULL constraint reports it
    END IF;

    SELECT q.question_date, q.question INTO q_date, payload
    FROM public.questions AS q
    WHERE q.question_id = NEW.question_id
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'question % does not exist', NEW.question_id
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    instant := clock_timestamp();
    IF q_date <> public.qa_business_date(instant) THEN
        RAISE EXCEPTION 'question % is for %, not today (%) in Asia/Kolkata',
                        NEW.question_id, q_date, public.qa_business_date(instant)
            USING ERRCODE = 'QA001';
    END IF;

    -- Fail closed: never score against a payload the API would not have accepted.
    opts := payload -> 'options';
    IF jsonb_typeof(payload) IS DISTINCT FROM 'object'
       OR jsonb_typeof(payload -> 'question') IS DISTINCT FROM 'string'
       OR (payload ->> 'question') !~ '[^[:space:]]'
       OR jsonb_typeof(opts) IS DISTINCT FROM 'object'
       OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(opts) AS k) IS DISTINCT FROM ARRAY['A', 'B', 'C', 'D']
       OR EXISTS (SELECT 1 FROM jsonb_each(opts) AS e
                  WHERE jsonb_typeof(e.value) <> 'string' OR (e.value #>> '{}') !~ '[^[:space:]]')
       OR (SELECT count(DISTINCT btrim(e.value)) FROM jsonb_each_text(opts) AS e) <> 4
       OR jsonb_typeof(payload -> 'answer') IS DISTINCT FROM 'string'
       OR NOT EXISTS (SELECT 1 FROM jsonb_each_text(opts) AS e WHERE e.value = payload ->> 'answer') THEN
        RAISE EXCEPTION 'question % has a malformed payload and cannot be answered', NEW.question_id
            USING ERRCODE = 'QA002';
    END IF;

    IF NEW.response_answer IS NULL THEN
        RETURN NEW;  -- NOT NULL constraint reports it
    END IF;

    correct := payload ->> 'answer';

    SELECT e.value INTO chosen
    FROM jsonb_each_text(opts) AS e
    WHERE btrim(e.value) = btrim(NEW.response_answer);

    IF NOT FOUND THEN
        RAISE EXCEPTION 'response_answer is not one of the options of question %', NEW.question_id
            USING ERRCODE = 'QA003';
    END IF;

    NEW.question        := payload ->> 'question';
    NEW.correct_answer  := correct;
    NEW.response_answer := chosen;
    NEW.is_correct      := (chosen = correct);
    NEW.responded_at    := instant;
    RETURN NEW;
END;
$$;

CREATE TRIGGER responses_before_insert
    BEFORE INSERT ON responses
    FOR EACH ROW EXECUTE FUNCTION qa_responses_before_insert();

CREATE FUNCTION qa_responses_block_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'responses are append-only: % is not allowed', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER responses_block_update_delete
    BEFORE UPDATE OR DELETE ON responses
    FOR EACH ROW EXECUTE FUNCTION qa_responses_block_mutation();

CREATE TRIGGER responses_block_truncate
    BEFORE TRUNCATE ON responses
    FOR EACH STATEMENT EXECUTE FUNCTION qa_responses_block_mutation();

-- Questions are insert-only, whether or not anyone has answered. A correction is a
-- new row for the same date. Deletion is refused too, preserving history.
CREATE FUNCTION qa_questions_block_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'questions are insert-only: % is not allowed; insert a new row instead', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER questions_block_update_delete
    BEFORE UPDATE OR DELETE ON questions
    FOR EACH ROW EXECUTE FUNCTION qa_questions_block_mutation();

CREATE TRIGGER questions_block_truncate
    BEFORE TRUNCATE ON questions
    FOR EACH STATEMENT EXECUTE FUNCTION qa_questions_block_mutation();

-- ---------------------------------------------------------------------------
-- 7. Final checks on the result.
-- ---------------------------------------------------------------------------
DO $$
BEGIN
    IF (SELECT data_type FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'questions' AND column_name = 'question') <> 'jsonb' THEN
        RAISE EXCEPTION '0003: questions.question is not jsonb';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'questions'::regclass AND contype IN ('u', 'c')) THEN
        RAISE EXCEPTION '0003: questions must have no UNIQUE or CHECK constraints';
    END IF;
    IF (SELECT count(*) FROM pg_trigger WHERE tgrelid IN ('questions'::regclass, 'responses'::regclass) AND NOT tgisinternal) <> 5 THEN
        RAISE EXCEPTION '0003: expected 5 protection triggers';
    END IF;
    IF (SELECT last_value FROM questions_question_id_seq) <> (SELECT last_value FROM qa_0003_seq WHERE t = 'questions')
       OR (SELECT last_value FROM responses_response_id_seq) <> (SELECT last_value FROM qa_0003_seq WHERE t = 'responses') THEN
        RAISE EXCEPTION '0003: identity sequence position changed';
    END IF;
END;
$$;

INSERT INTO schema_migrations (version, filename, checksum) VALUES ('0003', '0003_jsonb_questions_text_responses.sql', 'a13bca4c1c15f9615c8662811a214c82a97e6b9794d8629dfcc07a58ed8a1e5a');
COMMIT;

-- ============================================================================================
-- 0004_users.sql
-- ============================================================================================
BEGIN;

-- 0004: a users table that outlives questions and responses.
--   * users(user_id, user_name, created_at). user_id is the same identity responses store.
--   * Every response registers its user (ON CONFLICT DO NOTHING), so users appear here
--     even if their answers or questions are later removed.
--   * Users are never deleted: UPDATE, DELETE and TRUNCATE are always refused.
--   * Existing responses are backfilled with each user's most recent user_name.

CREATE TABLE users (
    user_id    text        PRIMARY KEY,
    user_name  text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

INSERT INTO users (user_id, user_name, created_at)
SELECT DISTINCT ON (user_id) user_id, user_name, min(responded_at) OVER (PARTITION BY user_id)
FROM responses
ORDER BY user_id, responded_at DESC, response_id DESC;

CREATE FUNCTION qa_responses_register_user()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO users (user_id, user_name) VALUES (NEW.user_id, NEW.user_name)
    ON CONFLICT (user_id) DO NOTHING;
    RETURN NEW;
END;
$$;

CREATE TRIGGER responses_register_user
    AFTER INSERT ON responses
    FOR EACH ROW EXECUTE FUNCTION qa_responses_register_user();

CREATE FUNCTION qa_users_block_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'users are never deleted or changed: % is not allowed', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER users_block_update_delete
    BEFORE UPDATE OR DELETE ON users
    FOR EACH ROW EXECUTE FUNCTION qa_users_block_mutation();

CREATE TRIGGER users_block_truncate
    BEFORE TRUNCATE ON users
    FOR EACH STATEMENT EXECUTE FUNCTION qa_users_block_mutation();

INSERT INTO schema_migrations (version, filename, checksum) VALUES ('0004', '0004_users.sql', '17508f653abdb1ea6e4f5011507d64b75887739a7bfecd70e9d89fc72afc0894');
COMMIT;

\echo 'schema ready: ' :DBNAME
